queries.Q030:
INSERT INTO employee (
    name,
    birthDate,
    mobile_phone,
    created_at,
    updated_at
) VALUES (
    '[1]',
    '[2]',
    '[3]',
    NOW(),
    NOW()
);
SET @emp_id := LAST_INSERT_ID();
INSERT INTO employment (
    employee_id,
    join_date,
    rehire_same,
    created_at,
    updated_at
) VALUES (
    @emp_id,
    '[4]',
    '[5]',
    NOW(),
    NOW()
);
INSERT INTO affiliation (
    employee_id,
    classification,
    position,
    created_at,
    updated_at
) VALUES (
    @emp_id,
    '[6]',
    '[7]',
    NOW(),
    NOW()
);

INSERT INTO account (
    employee_id,
    user_id,
    created_at,
    updated_at
) VALUES (
    @emp_id,
    '[8]',
    NOW(),
    NOW()
);

queries.Q040:
UPDATE employee SET name = '[1]', birthDate = CASE WHEN '[2]' != '' AND '[2]' != '00000000000000' THEN '[2]' ELSE birthDate END, mobile_phone = '[3]', updated_at = NOW() WHERE employee_id = [8];
UPDATE employment SET join_date = CASE WHEN '[4]' != '' THEN '[4]' ELSE join_date END, leave_date = CASE WHEN '[5]' = '9' THEN COALESCE(leave_date, NOW()) WHEN '[5]' = '0' THEN NULL ELSE leave_date END, rehire_same = CASE WHEN '[5]' = '1' THEN 1 WHEN '[5]' = '9' THEN 9 ELSE 0 END, updated_at = NOW() WHERE employee_id = [8];
UPDATE affiliation SET classification = '[6]', position = '[7]', updated_at = NOW() WHERE employee_id = [8]; UPDATE account SET user_id = '[9]', updated_at = NOW() WHERE employee_id = [8];

